        throw new CliError('candidates must be declared once, before any ballot', lineNumber)
      }
      if (tokens.length < 2) {
        throw new CliError('expected candidates <name>...', lineNumber)
      }
      const declared = []
      for (const name of tokens.slice(1)) {
        if (!NAME.test(name)) {
          throw new CliError(`invalid candidate name ${name}`, lineNumber)
        }
        if (candidateSet.has(name)) {
          throw new CliError(`candidate ${name} is declared twice`, lineNumber)
        }
        candidateSet.add(name)
        declared.push(name)
      }
      candidates = declared
    } else if (word === 'ballot') {
      if (candidates === null) {
        throw new CliError('candidates must be declared once, before any ballot', lineNumber)
      }
      if (tokens.length < 3) {
        throw new CliError('expected ballot <count> <candidate>...', lineNumber)
      }
      const count = tokens[1]
      if (!COUNT.test(count)) {
        throw new CliError('count must be a positive integer', lineNumber)
      }
      const names = []
      const seen = new Set()
      for (const name of tokens.slice(2)) {
        if (!candidateSet.has(name)) {
          throw new CliError(`unknown candidate ${name}`, lineNumber)
        }
        if (seen.has(name)) {
          throw new CliError(`candidate ${name} is repeated`, lineNumber)
        }
        seen.add(name)
        names.push(name)
      }
      ballots.push({ count: Number(count), names })
    } else {
      throw new CliError(`unknown directive ${word}`, lineNumber)
    }
  }

  if (candidates === null) {
    throw new CliError('no candidates')
  }

  return { candidates, ballots }
