{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260924T221218Z/cell-YzwZVG/src/election.js","content":"/**
 * Counts an instant-runoff election. Returns `{ rounds, winner }`, where
 * `rounds` holds, for each round counted, `{ votes, exhausted, eliminated }`:
 * `votes` maps every candidate continuing at the start of that round to its
 * count, `eliminated` is the name removed after that round or `null` for the
 * round that ended the election, and `winner` is the winning name or `null`.
 */
export function countElection({ candidates, ballots }) {
  let continuing = new Set(candidates)
  const rounds = []
  let winner = null

  for (;;) {
    const votes = new Map()
    for (const name of continuing) votes.set(name, 0)
    let exhausted = 0

    for (const ballot of ballots) {
      const choice = ballot.names.find((name) => continuing.has(name))
      if (choice === undefined) {
        exhausted += ballot.count
      } else {
        votes.set(choice, votes.get(choice) + ballot.count)
      }
    }

    const activeTotal = [...votes.values()].reduce((a, b) => a + b, 0)

    if (activeTotal === 0) {
      rounds.push({ votes, exhausted, eliminated: null })
      break
    }

    const majority = [...votes.entries()].find(([, count]) => count * 2 > activeTotal)
    if (majority) {
      winner = majority[0]
      rounds.push({ votes, exhausted, eliminated: null })
      break
    }

    const eliminated = pickElimination(votes, rounds)
    rounds.push({ votes, exhausted, eliminated })
    continuing.delete(eliminated)
  }

  return { rounds, winner }
}

/**
 * Chooses which candidate to eliminate after the round whose tallies are
 * `votes`, given the votes of every round counted so far including this one.
 */
function pickElimination(votes, priorRounds) {
  const fewest = Math.min(...votes.values())
  let tied = [...votes.keys()].filter((name) => votes.get(name) === fewest)
  const history = [...priorRounds.map((r) => r.votes), votes]

  for (const roundVotes of history) {
    if (tied.length === 1) break
    const counts = tied.map((name) => roundVotes.get(name))
    const min = Math.min(...counts)
    const max = Math.max(...counts)
    if (min !== max) {
      tied = tied.filter((name) => roundVotes.get(name) === min)
    }
  }

  if (tied.length === 1) return tied[0]
  return tied.reduce((last, name) => (name > last ? name : last))
}
"}

