/**
 * The command. `node src/cli.js rounds` prints every round of the instant-runoff
 * count read from standard input, and `node src/cli.js tally` prints only how
 * many rounds ran and who won.
 */
import { CliError } from './errors.js'
import { parseElection } from './parser.js'
import { countElection } from './election.js'

function formatRound(round) {
  const entries = [...round.votes.entries()]
  entries.sort(([nameA, countA], [nameB, countB]) => {
    if (countA !== countB) return countB - countA
    return nameA < nameB ? -1 : nameA > nameB ? 1 : 0
  })
  const parts = entries.map(([name, count]) => `${name}=${count}`)
  parts.push(`exhausted=${round.exhausted}`)
  return parts.join(' ')
}

function main() {
  const mode = process.argv[2]
  if (process.argv.length !== 3 || (mode !== 'rounds' && mode !== 'tally')) {
    throw new CliError('usage: cli.js rounds|tally')
  }

  const input = readStdin()
  const election = parseElection(input)
  const { rounds, winner } = countElection(election)

  const lines = []
  if (mode === 'rounds') {
    rounds.forEach((round, index) => {
      lines.push(`round ${index + 1}: ${formatRound(round)}`)
      if (round.eliminated !== null) lines.push(`eliminated ${round.eliminated}`)
    })
  } else {
    lines.push(`rounds ${rounds.length}`)
  }
  lines.push(winner === null ? 'no winner' : `winner ${winner}`)

  process.stdout.write(lines.join('\n') + '\n')
}

function readStdin() {
  const fs = require('node:fs')
  return fs.readFileSync(0, 'utf8')
}

try {
  main()
} catch (error) {
  if (error instanceof CliError) {
    const location = error.line === undefined ? '' : `line ${error.line}: `
    process.stderr.write(`error: ${location}${error.message}\n`)
    process.exit(2)
